import React, { useEffect, useState, useRef } from 'react'
import { useNavigate, useParams } from 'react-router-dom'
import { useAuth } from '../lib/AuthContext'
import { supabase } from '../lib/supabase'

export default function ChatScreen() {
  const { contactUsername } = useParams()
  const { session, canSend } = useAuth()
  const navigate = useNavigate()

  const [messages, setMessages] = useState([])
  const [conversationId, setConversationId] = useState(null)
  const [input, setInput] = useState('')
  const [editingId, setEditingId] = useState(null)
  const [editContent, setEditContent] = useState('')
  const [recording, setRecording] = useState(false)
  const messagesEndRef = useRef(null)
  const channelRef = useRef(null)

  const myUsername = session.client.username
  const otherUsername = contactUsername
  const convoKey = [myUsername, otherUsername].sort().join('::')

  const initials = (str) => str ? str.slice(0,2).toUpperCase() : '??'
  const avatarColors = [['#2a1f05','#F5C518'],['#1a1f2e','#85b7eb'],['#1e2a1e','#5dcaa5'],['#2a1a1e','#d85a30'],['#221a2e','#d4537e']]
  const colorFor = (str) => avatarColors[(str||'').charCodeAt(0) % avatarColors.length]
  const [obg, ofg] = colorFor(otherUsername)

  useEffect(() => {
    async function init() {
      let { data: convo } = await supabase
        .from('conversations').select('*').eq('convo_key', convoKey).single()

      if (!convo) {
        const { data: newConvo, error } = await supabase
          .from('conversations')
          .insert({ client_id: session.client.id, user_id: null, contact_username: convoKey, convo_key: convoKey })
          .select().single()
        if (error) {
          const { data: retry } = await supabase.from('conversations').select('*').eq('convo_key', convoKey).single()
          convo = retry
        } else { convo = newConvo }
      }

      if (!convo) return
      setConversationId(convo.id)

      const { data: msgs } = await supabase
        .from('messages').select('*')
        .eq('conversation_id', convo.id).eq('is_deleted', false)
        .order('created_at', { ascending: true })
      setMessages(msgs || [])

      if (channelRef.current) { await supabase.removeChannel(channelRef.current); channelRef.current = null }

      const channel = supabase.channel(`chat-${convo.id}-${Date.now()}`)
        .on('postgres_changes', { event:'INSERT', schema:'public', table:'messages', filter:`conversation_id=eq.${convo.id}` },
          (payload) => setMessages(prev => prev.find(m => m.id === payload.new.id) ? prev : [...prev, payload.new]))
        .on('postgres_changes', { event:'UPDATE', schema:'public', table:'messages', filter:`conversation_id=eq.${convo.id}` },
          (payload) => {
            if (payload.new.is_deleted) setMessages(prev => prev.filter(m => m.id !== payload.new.id))
            else setMessages(prev => prev.map(m => m.id === payload.new.id ? payload.new : m))
          })
      channel.subscribe()
      channelRef.current = channel
    }
    init()
    return () => { if (channelRef.current) { supabase.removeChannel(channelRef.current); channelRef.current = null } }
  }, [contactUsername, session])

  useEffect(() => { messagesEndRef.current?.scrollIntoView({ behavior:'smooth' }) }, [messages])

  async function handleSend(isTranscribed = false) {
    if (!input.trim() || !canSend || !conversationId) return
    const content = input.trim()
    setInput('')
    const { data: msg, error } = await supabase.from('messages').insert({
      conversation_id: conversationId, client_id: session.client.id,
      sender:'user', sent_by_user_id: session.user.id, content,
      is_transcribed: isTranscribed,
      meta: { from_username: myUsername, to_username: otherUsername }
    }).select().single()
    if (!error) {
      await supabase.from('conversations').update({ last_message: content, last_message_at: msg.created_at }).eq('id', conversationId)
      await supabase.from('audit_log').insert({ event_type:'message_sent', client_id: session.client.id, user_id: session.user.id, message_id: msg.id, meta: { from: myUsername, to: otherUsername, preview: content.slice(0,60) } })
    }
  }

  async function handleEdit(id) {
    await supabase.from('messages').update({ content: editContent, is_edited: true, edited_at: new Date().toISOString() }).eq('id', id)
    setMessages(prev => prev.map(m => m.id === id ? { ...m, content: editContent, is_edited: true } : m))
    setEditingId(null)
  }

  async function handleDelete(id) {
    await supabase.from('messages').update({ is_deleted: true }).eq('id', id)
    setMessages(prev => prev.filter(m => m.id !== id))
  }

  function handleMic() {
    if (!('webkitSpeechRecognition' in window) && !('SpeechRecognition' in window)) {
      alert('Voice input not supported on this browser. Try Chrome.')
      return
    }
    if (recording) { setRecording(false); return }
    const SR = window.SpeechRecognition || window.webkitSpeechRecognition
    const recognition = new SR()
    recognition.lang = 'en-US'; recognition.interimResults = false; recognition.maxAlternatives = 1
    recognition.onstart = () => setRecording(true)
    recognition.onresult = (e) => { setInput(prev => prev ? prev + ' ' + e.results[0][0].transcript : e.results[0][0].transcript); setRecording(false) }
    recognition.onerror = () => setRecording(false)
    recognition.onend = () => setRecording(false)
    recognition.start()
  }

  function isMine(msg) {
    if (msg.meta?.from_username) return msg.meta.from_username === myUsername
    return msg.client_id === session.client.id
  }

  function formatTime(ts) { return new Date(ts).toLocaleTimeString([], { hour:'2-digit', minute:'2-digit' }) }

  return (
    <div style={s.wrap}>
      <div style={s.header}>
        <button style={s.backBtn} onClick={() => navigate('/inbox')}>
          <svg width="22" height="22" viewBox="0 0 24 24" fill="none" stroke="#F5C518" strokeWidth="2.5" strokeLinecap="round"><path d="M19 12H5M12 5l-7 7 7 7"/></svg>
        </button>
        <div style={{ ...s.headerAvatar, background:obg, color:ofg }}>{initials(otherUsername)}</div>
        <div style={s.headerInfo}>
          <div style={s.headerHandle}>@{otherUsername}</div>
        </div>
      </div>

      <div style={s.threadBanner}>
        {session.user.full_name} · sending as @{myUsername}
      </div>

      <div style={s.messages}>
        {messages.length === 0 && <div style={s.noMessages}>no messages yet — say hello!</div>}
        {messages.map(msg => {
          const mine = isMine(msg)
          return (
            <div key={msg.id} style={{ ...s.msgRow, justifyContent: mine ? 'flex-end' : 'flex-start' }}>
              {!mine && <div style={{ ...s.msgAvatar, background:obg, color:ofg }}>{initials(otherUsername)}</div>}
              <div style={{ maxWidth:'75%' }}>
                {editingId === msg.id ? (
                  <div style={s.editWrap}>
                    <input style={s.editInput} value={editContent} onChange={e => setEditContent(e.target.value)} onKeyDown={e => e.key === 'Enter' && handleEdit(msg.id)} autoFocus />
                    <button style={s.editSave} onClick={() => handleEdit(msg.id)}>save</button>
                    <button style={s.editCancel} onClick={() => setEditingId(null)}>cancel</button>
                  </div>
                ) : (
                  <div style={{ ...s.bubble, ...(mine ? s.bubbleMine : s.bubbleTheirs) }}
                    onDoubleClick={() => { if (mine) { setEditingId(msg.id); setEditContent(msg.content) } }}>
                    {msg.content}
                  </div>
                )}
                <div style={{ ...s.msgMeta, justifyContent: mine ? 'flex-end' : 'flex-start' }}>
                  <span style={s.msgTime}>{formatTime(msg.created_at)}</span>
                  {msg.is_edited && <span style={s.msgEdited}>edited</span>}
                  {msg.is_transcribed && <span style={s.msgTranscribed}>🎤</span>}
                  {mine && !editingId && (
                    <>
                      <span style={s.actionLink} onClick={() => { setEditingId(msg.id); setEditContent(msg.content) }}>edit</span>
                      <span style={{ ...s.actionLink, color:'#e24b4a' }} onClick={() => handleDelete(msg.id)}>delete</span>
                    </>
                  )}
                </div>
              </div>
              {mine && <div style={{ ...s.msgAvatar, background:'#2a1f05', color:'#F5C518' }}>{initials(myUsername)}</div>}
            </div>
          )
        })}
        <div ref={messagesEndRef} />
      </div>

      {canSend ? (
        <div style={s.inputRow}>
          <div style={s.inputWrap}>
            <textarea style={s.input} placeholder="message..." value={input} rows={1}
              onChange={e => setInput(e.target.value)}
              onKeyDown={e => { if (e.key === 'Enter' && !e.shiftKey) { e.preventDefault(); handleSend() } }} />
            <button style={{ ...s.micBtn, color: recording ? '#e24b4a' : '#888aa0' }} onClick={handleMic}>
              <svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round">
                <rect x="9" y="3" width="6" height="11" rx="3"/>
                <path d="M5 10c0 3.866 3.134 7 7 7s7-3.134 7-7M12 17v4M8 21h8"/>
              </svg>
            </button>
          </div>
          <button style={s.sendBtn} onClick={() => handleSend()}>
            <svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="#181922" strokeWidth="2.5" strokeLinecap="round"><path d="M22 2L11 13M22 2L15 22 11 13 2 9l20-7z"/></svg>
          </button>
        </div>
      ) : (
        <div style={s.readOnlyBar}>read only · you cannot send messages</div>
      )}
    </div>
  )
}

const s = {
  wrap: { background:'#181922', minHeight:'100vh', display:'flex', flexDirection:'column', fontFamily:"'Syne',sans-serif", color:'#ffffff', maxWidth:480, margin:'0 auto' },
  header: { padding:'16px 20px 14px', borderBottom:'0.5px solid #2a2d3e', display:'flex', alignItems:'center', gap:14, flexShrink:0 },
  backBtn: { background:'none', border:'none', cursor:'pointer', padding:4, display:'flex', flexShrink:0 },
  headerAvatar: { width:42, height:42, borderRadius:12, display:'flex', alignItems:'center', justifyContent:'center', fontSize:15, fontWeight:700, flexShrink:0 },
  headerInfo: { flex:1 },
  headerHandle: { fontSize:18, fontWeight:700, color:'#ffffff' },
  threadBanner: { background:'#1e1c0a', borderBottom:'0.5px solid #F5C51830', padding:'8px 20px', fontSize:12, fontFamily:"'DM Mono',monospace", color:'#F5C51899', flexShrink:0 },
  messages: { flex:1, overflowY:'auto', padding:'18px 20px', display:'flex', flexDirection:'column', gap:14 },
  noMessages: { textAlign:'center', color:'#444', fontSize:14, fontFamily:"'DM Mono',monospace", marginTop:40 },
  msgRow: { display:'flex', gap:10, alignItems:'flex-end' },
  msgAvatar: { width:32, height:32, borderRadius:10, fontSize:12, fontWeight:700, display:'flex', alignItems:'center', justifyContent:'center', flexShrink:0 },
  bubble: { padding:'13px 17px', borderRadius:18, fontSize:16, lineHeight:1.6 },
  bubbleMine: { background:'#F5C518', color:'#181922', borderBottomRightRadius:4, fontWeight:500 },
  bubbleTheirs: { background:'#22242f', color:'#ffffff', border:'0.5px solid #2a2d3e', borderBottomLeftRadius:4 },
  msgMeta: { display:'flex', alignItems:'center', gap:8, marginTop:5, padding:'0 4px' },
  msgTime: { fontSize:11, color:'#444', fontFamily:"'DM Mono',monospace" },
  msgEdited: { fontSize:10, color:'#444', fontFamily:"'DM Mono',monospace" },
  msgTranscribed: { fontSize:12 },
  actionLink: { fontSize:11, color:'#F5C518', cursor:'pointer', fontFamily:"'DM Mono',monospace" },
  editWrap: { display:'flex', gap:8, alignItems:'center' },
  editInput: { background:'#22242f', border:'1px solid #F5C518', borderRadius:10, color:'#ffffff', padding:'8px 12px', fontSize:15, fontFamily:"'Syne',sans-serif", outline:'none', width:200 },
  editSave: { background:'#F5C518', border:'none', color:'#181922', fontSize:12, fontFamily:"'DM Mono',monospace", padding:'5px 12px', borderRadius:6, cursor:'pointer', fontWeight:600 },
  editCancel: { background:'none', border:'none', color:'#888aa0', fontSize:12, fontFamily:"'DM Mono',monospace", cursor:'pointer' },
  inputRow: { padding:'12px 16px 24px', borderTop:'0.5px solid #2a2d3e', display:'flex', alignItems:'flex-end', gap:10, flexShrink:0 },
  inputWrap: { flex:1, background:'#22242f', border:'0.5px solid #2a2d3e', borderRadius:22, display:'flex', alignItems:'center', padding:'10px 16px', gap:10, boxShadow:'6px 6px 12px #12141c, -3px -3px 8px #2a2d3e' },
  input: { flex:1, background:'none', border:'none', outline:'none', color:'#ffffff', fontSize:16, fontFamily:"'Syne',sans-serif", resize:'none', maxHeight:100, lineHeight:1.5 },
  micBtn: { background:'none', border:'none', cursor:'pointer', display:'flex', alignItems:'center', flexShrink:0 },
  sendBtn: { width:46, height:46, borderRadius:'50%', background:'#F5C518', border:'none', cursor:'pointer', display:'flex', alignItems:'center', justifyContent:'center', flexShrink:0, boxShadow:'6px 6px 12px #12141c, -3px -3px 8px #2a2d3e' },
  readOnlyBar: { padding:'14px 20px', borderTop:'0.5px solid #2a2d3e', textAlign:'center', fontSize:13, fontFamily:"'DM Mono',monospace", color:'#444', flexShrink:0 }
}
